CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NULL,created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS preferences (user_id VARCHAR(64) PRIMARY KEY,capacity DECIMAL(5,2) NOT NULL DEFAULT 4,day_start INT NOT NULL DEFAULT 540,day_end INT NOT NULL DEFAULT 1080,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS courses (user_id VARCHAR(64) NOT NULL,id VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,code VARCHAR(30) NOT NULL DEFAULT '',professor VARCHAR(100) NOT NULL DEFAULT '',color VARCHAR(7) NOT NULL,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (user_id VARCHAR(64) NOT NULL,id VARCHAR(64) NOT NULL,title VARCHAR(140) NOT NULL,description TEXT NOT NULL,course_id VARCHAR(64) NOT NULL,due_date DATE NOT NULL,hours DECIMAL(6,2) NOT NULL,progress DECIMAL(5,2) NOT NULL,difficulty TINYINT NOT NULL,importance TINYINT NOT NULL,type VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,priority_calculated TINYINT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id,course_id) REFERENCES courses(user_id,id) ON DELETE CASCADE,INDEX due_lookup(user_id,due_date,status));
CREATE TABLE IF NOT EXISTS study_sessions (user_id VARCHAR(64) NOT NULL,id VARCHAR(64) NOT NULL,task_id VARCHAR(64) NOT NULL,date DATE NOT NULL,start_minute INT NULL,hours DECIMAL(6,2) NOT NULL,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id,task_id) REFERENCES tasks(user_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS recommendations (user_id VARCHAR(64) NOT NULL,id VARCHAR(64) NOT NULL,task_id VARCHAR(64) NULL,source VARCHAR(30) NOT NULL,model VARCHAR(100) NULL,priority TINYINT NOT NULL DEFAULT 0,text TEXT NOT NULL,created_at DATETIME(3) NOT NULL,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash CHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX expiry_lookup(expires_at));
CREATE TABLE IF NOT EXISTS oauth_identities (provider VARCHAR(20) NOT NULL,provider_user_id VARCHAR(255) NOT NULL,user_id VARCHAR(64) NOT NULL,PRIMARY KEY(provider,provider_user_id),UNIQUE KEY user_provider(user_id,provider),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS oauth_flows (state_hash CHAR(64) PRIMARY KEY,provider VARCHAR(20) NOT NULL,verifier VARCHAR(128) NOT NULL,user_id VARCHAR(64) NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX flow_expiry(expires_at));
CREATE TABLE IF NOT EXISTS chat_actions (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,kind VARCHAR(30) NOT NULL,payload JSON NOT NULL,status VARCHAR(15) NOT NULL DEFAULT 'pending',result_id VARCHAR(64) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX action_owner(user_id,id));
